// Exported for browser-level regression tests; no DOM or data is changed.
export function installCasePrefetch(){
 const original=window.fetch.bind(window),entries=new Map(),ambiguous=new Set(),completed=new Set(),active=new Map();let queue=[],generation=null,ready=false,scheduled=false;
 const dataPath=pathname=>window.__matterReportDataPath?.(pathname)??pathname;
 const hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x),identity=(date,name)=>JSON.stringify([date,name]);
 function record(button){if(!ready||!button||button.tagName!=='BUTTON')return null;const row=button.closest('tr'),cell=row?.querySelector('td'),name=cell?.querySelector('strong')?.textContent,date=cell?.querySelector('small')?.textContent;if(!name||button.getAttribute('aria-label')!=='Review '+name||!/^\d{4}-\d{2}-\d{2}(?: · Original 52)?$/.test(date||''))return null;return entries.get(identity(date.slice(0,10),name))||null;}
 function visible(){return [...document.querySelectorAll('button[aria-label^="Review "]')].filter(b=>b.getClientRects().length&&record(b));}
 function drain(){while(active.size<1&&queue.length){const ref=queue.shift(),url=new URL(ref.url,location.href);const key=url.href;if(active.has(key)||completed.has(key))continue;const controller=new AbortController();active.set(key,controller);Promise.all([key,...(ref.photo?[new URL(ref.photo,location.href).href]:[])].map(path=>original(path,{headers:{'X-Report-Prefetch':'1'},credentials:'same-origin',cache:'no-store',signal:controller.signal}).then(async response=>{if(response.ok)await response.arrayBuffer();else await response.body?.cancel();return response.ok;}))).then(results=>{if(results[0])completed.add(key);}).catch(()=>{}).finally(()=>{active.delete(key);drain();});}}
 function schedule(button){if(!ready||generation!==window.__matterReportingGeneration||document.visibilityState==='hidden')return;const buttons=visible(),index=button?buttons.indexOf(button):-1,selected=buttons.slice(Math.max(index,0),Math.max(index,0)+(index<0?2:3));queue=selected.map(record).filter(Boolean);drain();}
 function scan(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;schedule();},80);}
 async function learn(response,url){const size=response.headers.get('X-Report-Bytes');if(!/^[0-9]+$/.test(size||'')||Number(size)>64*1024*1024)return;const copy=response.clone(),reader=copy.body.getReader(),chunks=[];let total=0;try{while(true){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>Number(size))throw Error('Oversized report');chunks.push(value);}if(total!==Number(size))return;const bytes=new Uint8Array(total);let at=0;for(const chunk of chunks){bytes.set(chunk,at);at+=chunk.length;}const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(dataPath(url.pathname)!=='/report-data/snapshot-'+hash+'.json')return;const app=JSON.parse(new TextDecoder().decode(bytes)),rows=app.queries?.[app.matter?.validatedReporting?.queryId]?.rows,cases=app.matter?.lazyDeliveryDetails?.cases,nextGeneration=url.searchParams.get('generation')||window.__matterReportingGeneration;if(!hex(nextGeneration)||nextGeneration!==window.__matterReportingGeneration||!Array.isArray(rows)||rows.length>100000)return;entries.clear();ambiguous.clear();completed.clear();queue=[];for(const c of active.values())c.abort();generation=nextGeneration;for(const row of rows){const ref=cases?.[row.key],name=row.delivery?.customer;if(typeof name!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(row.date||''))continue;const id=identity(row.date,name);if(entries.has(id)||ambiguous.has(id)){entries.delete(id);ambiguous.add(id);continue;}if(ref?.count===1&&hex(ref.sha256)&&ref.url==='report-data/detail-'+ref.sha256+'.json')entries.set(id,{...ref,...(row.delivery?.upload&&hex(app.matter.validatedReporting?.snapshotHash)?{photo:'/api/reporting/photo/image?'+new URLSearchParams({record:row.key,snapshot:app.matter.validatedReporting.snapshotHash})}:{})});}ready=true;scan();}catch{await reader.cancel().catch(()=>{});}}
 window.fetch=async(input,init)=>{const response=await original(input,init),url=new URL(typeof input==='string'||input instanceof URL?input:input.url,location.href);if(url.origin===location.origin&&/^\/report-data\/snapshot-[a-f0-9]{64}\.json$/.test(dataPath(url.pathname))&&response.ok)void learn(response,url);return response;};
 const start=()=>{new MutationObserver(scan).observe(document.body,{childList:true,subtree:true});for(const type of ['pointerover','focusin','click'])document.addEventListener(type,event=>{const button=event.target?.closest?.('button[aria-label^="Review "]');if(record(button))schedule(button);});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){queue=[];for(const c of active.values())c.abort();}else scan();});scan();};
 if(document.body)start();else document.addEventListener('DOMContentLoaded',start,{once:true});
}
export function addCasePrefetch(html){if(typeof html!=='string'||html.split('</head>').length!==2)throw Error('Renderer unavailable');return html.replace('</head>','<script>('+installCasePrefetch.toString()+')();</script></head>');}
